    /** How many times over the renderer draws a creature: 1 for all but the few built small. */
    public static float scale(String id) {
        return switch(id) {
            case "colossus_warden" -> 1.75F;
            case "slag_titan" -> 2F;
            case "bog_matriarch" -> 2F;
            case "cairn_wight" -> 2F;
            case "prism_serpent" -> 2F;
            case "vault_sentinel" -> 2F;
            case "tide_drummer" -> 2F;
            case "stampede_spirit" -> 2F;
            case "storm_roc" -> 2F;
            case "the_unsung" -> 2F;
            default -> 1F;
        };
    }

